"use client";

import Link from "next/link";
import { useRouter } from "next/navigation";
import { useMemo, useState, useTransition } from "react";
import { ArrowLeft, Banknote, CalendarCheck2, CalendarClock, ChartNoAxesCombined, ChevronDown, CircleEuro, Landmark, Pencil, Plus, ReceiptText, Settings2, Tags, X } from "lucide-react";
import { closeFinancialMonth, createExpense, createExpenseCategory, createRecurringPlan, deleteExpense, reopenFinancialMonth, saveDailyRevenue, updateExpense, updateExpenseCategory, updateRecurringPlan, validateCostMonth, type ExpenseActionResult } from "./actions";
import styles from "./expense-dashboard.module.css";

type CostType = "fixed" | "variable";
type Category = { id: number; name: string; cost_type: CostType; color: string; monthly_budget_cents: number; is_active: boolean };
type Expense = { id: number; category_id: number; description: string; supplier: string | null; invoice_number: string | null; expense_date: string; due_date: string | null; paid_date: string | null; amount_net_cents: number; vat_cents: number; total_cents: number; payment_status: "planned" | "due" | "paid"; payment_method: string | null; recurrence: string; is_estimate: boolean; notes: string | null };
type Plan = { id: number; category_id: number | null; name: string; supplier: string | null; annual_amount_cents: number | null; competence_start: string; competence_end: string; payment_frequency: string; payment_months: number[]; payment_day: number; payment_method: string | null; is_estimate: boolean; is_active: boolean; notes: string | null; series_id:string; version_number:number; replaced_at:string|null; replaced_by:number|null };
type PlanMonth = { id: number; plan_id: number; competence_month: string; competence_amount_cents: number | null; due_date: string | null; cash_amount_cents: number | null; status: "planned" | "confirmed" | "paid"; paid_date: string | null; notes: string | null; confirmed_at:string|null };
type Revenue = { id: number; revenue_date: string; cash_cents: number; pos_cents: number; other_cents: number; refunds_cents: number; receipt_count: number | null; notes: string | null; is_closed: boolean };
type StaffCost = { id:number; competence_month:string; confirmed_base_hours:number; confirmed_extra_hours:number; base_hourly_rate_cents:number; extra_hourly_rate_cents:number; status:string };
type Closure={id:number;period_start:string;closed_at:string;notes:string|null};
const STATUS = { planned: "Pianificata", due: "Da pagare", paid: "Pagata" } as const;
const METHODS: Record<string, string> = { bank_transfer: "Bonifico", direct_debit: "Addebito diretto", card: "Carta", cash: "Contanti", other: "Altro" };
const RECURRENCES: Record<string, string> = { none: "Non ricorrente", monthly: "Mensile", bimonthly: "Bimestrale", quarterly: "Trimestrale", yearly: "Annuale" };
const euro = (cents: number) => (cents / 100).toLocaleString("it-IT", { style: "currency", currency: "EUR" });
const monthLabel = (month: string) => new Intl.DateTimeFormat("it-IT", { month: "long", year: "numeric", timeZone: "UTC" }).format(new Date(`${month}-01T12:00:00Z`));
const currentMonth = () => new Date().toISOString().slice(0, 7);
const currentDay = () => new Date().toISOString().slice(0, 10);
type PeriodMode = "day"|"week"|"month"|"quarter"|"year";
const currentQuarter = () => { const now=new Date(); return `${now.getFullYear()}-Q${Math.floor(now.getMonth()/3)+1}`; };
const frequencyMultiplier = (frequency:string) => (({monthly:12,bimonthly:6,quarterly:4,yearly:1,custom:1} as Record<string,number>)[frequency] ?? 1);
const frequencyLabel = (frequency:string) => (({monthly:"mensile",bimonthly:"bimestrale",quarterly:"trimestrale",yearly:"annuale",custom:"personalizzato"} as Record<string,string>)[frequency] ?? "periodico");
function isoWeek(dateString = currentDay()) { const date = new Date(`${dateString}T12:00:00Z`); const day = date.getUTCDay() || 7; date.setUTCDate(date.getUTCDate() + 4 - day); const yearStart = new Date(Date.UTC(date.getUTCFullYear(), 0, 1)); return `${date.getUTCFullYear()}-W${String(Math.ceil((((date.getTime() - yearStart.getTime()) / 86400000) + 1) / 7)).padStart(2,"0")}`; }
function selectedRange(mode:PeriodMode,day:string,week:string,month:string,quarter:string,year:string){if(mode==="day")return{start:day,end:day,label:new Date(`${day}T12:00:00Z`).toLocaleDateString("it-IT",{day:"numeric",month:"long",year:"numeric"})};if(mode==="month"){const date=new Date(`${month}-01T12:00:00Z`);return{start:`${month}-01`,end:new Date(Date.UTC(date.getUTCFullYear(),date.getUTCMonth()+1,0)).toISOString().slice(0,10),label:monthLabel(month)}}if(mode==="quarter"){const [quarterYear,quarterNumber]=quarter.split("-Q").map(Number);const startMonth=(quarterNumber-1)*3;const first=new Date(Date.UTC(quarterYear,startMonth,1,12));const last=new Date(Date.UTC(quarterYear,startMonth+3,0,12));return{start:first.toISOString().slice(0,10),end:last.toISOString().slice(0,10),label:`${quarterNumber}° trimestre ${quarterYear}`}}if(mode==="year")return{start:`${year}-01-01`,end:`${year}-12-31`,label:year};const [weekYear,weekNumber]=week.split("-W").map(Number);const jan4=new Date(Date.UTC(weekYear,0,4,12));const monday=new Date(jan4);monday.setUTCDate(jan4.getUTCDate()-(jan4.getUTCDay()||7)+1+(weekNumber-1)*7);const sunday=new Date(monday);sunday.setUTCDate(monday.getUTCDate()+6);return{start:monday.toISOString().slice(0,10),end:sunday.toISOString().slice(0,10),label:`${monday.toLocaleDateString("it-IT",{day:"numeric",month:"short"})} – ${sunday.toLocaleDateString("it-IT",{day:"numeric",month:"short",year:"numeric"})}`}}
function makeTrend(start:string,end:string,mode:PeriodMode,total:(start:string,end:string)=>number){const first=new Date(`${start}T12:00:00Z`);const last=new Date(`${end}T12:00:00Z`);const bins:{key:string;label:string;total:number}[]=[];if(mode==="year"||mode==="quarter"){for(let cursor=new Date(first);cursor<=last;cursor=new Date(Date.UTC(cursor.getUTCFullYear(),cursor.getUTCMonth()+1,1,12))){const to=new Date(Date.UTC(cursor.getUTCFullYear(),cursor.getUTCMonth()+1,0,12));bins.push({key:cursor.toISOString(),label:cursor.toLocaleDateString("it-IT",{month:"short"}),total:total(cursor.toISOString().slice(0,10),to.toISOString().slice(0,10))})}return bins}if(mode==="week"){for(const cursor=new Date(first);cursor<=last;cursor.setUTCDate(cursor.getUTCDate()+1)){const key=cursor.toISOString().slice(0,10);bins.push({key,label:cursor.toLocaleDateString("it-IT",{weekday:"short",day:"numeric"}),total:total(key,key)})}return bins}return[{key:start,label:mode==="day"?new Date(`${start}T12:00:00Z`).toLocaleDateString("it-IT",{weekday:"short",day:"numeric"}):new Date(`${start}T12:00:00Z`).toLocaleDateString("it-IT",{month:"long"}),total:total(start,end)}]}

export function ExpenseDashboard({ categories, expenses, plans, planMonths, revenues, staffCosts, closures, historyReady, financeReady }: { categories: Category[]; expenses: Expense[]; plans: Plan[]; planMonths: PlanMonth[]; revenues: Revenue[]; staffCosts:StaffCost[]; closures:Closure[]; historyReady:boolean; financeReady: boolean }) {
  const router = useRouter();
  const [tab, setTab] = useState<"overview" | "plans" | "closures" | "daily" | "revenues" | "ledger" | "expenses" | "categories">("overview");
  const [month, setMonth] = useState(currentMonth());
  const [periodMode, setPeriodMode] = useState<PeriodMode>("month");
  const [day, setDay] = useState(currentDay()); const [week, setWeek] = useState(isoWeek()); const [quarter,setQuarter]=useState(currentQuarter()); const [year, setYear] = useState(String(new Date().getFullYear()));
  const [expenseEditor, setExpenseEditor] = useState<Expense | "new" | null>(null);
  const [categoryEditor, setCategoryEditor] = useState<Category | "new" | null>(null);
  const [planEditor, setPlanEditor] = useState<Plan | "new" | null>(null);
  const [revenueEditor, setRevenueEditor] = useState<Revenue | "new" | null>(null);
  const [showPlanHistory,setShowPlanHistory]=useState(false);
  const [fixedLedgerOpen,setFixedLedgerOpen]=useState(false);
  const [error, setError] = useState("");
  const [pending, startTransition] = useTransition();
  const categoryMap = useMemo(() => new Map(categories.map((category) => [category.id, category])), [categories]);
  const range = useMemo(() => selectedRange(periodMode,day,week,month,quarter,year),[periodMode,day,week,month,quarter,year]);
  const monthExpenses = useMemo(() => expenses.filter((expense) => expense.expense_date >= range.start && expense.expense_date <= range.end), [expenses, range]);
  const monthRevenues = useMemo(() => revenues.filter((entry) => entry.revenue_date >= range.start && entry.revenue_date <= range.end), [revenues, range]);
  const monthPlanRows = useMemo(() => planMonths.filter((entry) => entry.competence_month >= range.start.slice(0,7)+"-01" && entry.competence_month <= range.end), [planMonths, range]);
  const fixedCostPlans=useMemo(()=>{if(showPlanHistory)return plans;const target=`${month}-01`;const series=new Map<string,Plan[]>();plans.forEach(plan=>{const key=plan.series_id||String(plan.id);series.set(key,[...(series.get(key)||[]),plan])});return [...series.values()].map(versions=>versions.sort((a,b)=>b.version_number-a.version_number).find(plan=>plan.competence_start<=target&&plan.competence_end>=target)||versions.find(plan=>plan.is_active)||versions[0]).filter(Boolean) as Plan[]},[plans,month,showPlanHistory]);
  const monthClosed=closures.some(closure=>closure.period_start===`${month}-01`);
  const fixedCompetenceRows=useMemo(()=>{const rows=planMonths.filter(item=>item.competence_month===`${month}-01`&&item.competence_amount_cents!=null).map(item=>({key:`fixed-${item.id}`,title:plans.find(plan=>plan.id===item.plan_id)?.name??"Costo fisso",amount:item.competence_amount_cents??0,status:item.status}));const staff=staffCosts.filter(item=>item.status==="confirmed"&&item.competence_month===`${month}-01`).reduce((sum,item)=>sum+Math.round(item.confirmed_base_hours*item.base_hourly_rate_cents+item.confirmed_extra_hours*item.extra_hourly_rate_cents),0);if(staff>0)rows.push({key:`staff-${month}`,title:"Costo del personale",amount:staff,status:"confirmed"});return rows},[planMonths,plans,staffCosts,month]);
  const fixedCompetenceTotal=fixedCompetenceRows.reduce((sum,item)=>sum+item.amount,0);
  const closureSummaries=useMemo(()=>{const keys=new Set<string>();expenses.forEach(item=>keys.add(item.expense_date.slice(0,7)));revenues.forEach(item=>keys.add(item.revenue_date.slice(0,7)));planMonths.forEach(item=>keys.add(item.competence_month.slice(0,7)));staffCosts.forEach(item=>keys.add(item.competence_month.slice(0,7)));closures.forEach(item=>keys.add(item.period_start.slice(0,7)));keys.add(currentMonth());return [...keys].filter(key=>key<=currentMonth()).sort((a,b)=>b.localeCompare(a)).map(key=>{const planFixed=planMonths.filter(item=>item.competence_month.startsWith(key)).reduce((sum,item)=>sum+(item.competence_amount_cents??0),0);const staff=staffCosts.filter(item=>item.status==="confirmed"&&item.competence_month.startsWith(key)).reduce((sum,item)=>sum+Math.round(item.confirmed_base_hours*item.base_hourly_rate_cents+item.confirmed_extra_hours*item.extra_hourly_rate_cents),0);const periodExpenses=expenses.filter(item=>item.expense_date.startsWith(key));const registeredFixed=periodExpenses.filter(item=>categoryMap.get(item.category_id)?.cost_type==="fixed").reduce((sum,item)=>sum+item.total_cents,0);const variable=periodExpenses.filter(item=>categoryMap.get(item.category_id)?.cost_type!=="fixed").reduce((sum,item)=>sum+item.total_cents,0);const income=revenues.filter(item=>item.revenue_date.startsWith(key)).reduce((sum,item)=>sum+item.cash_cents+item.pos_cents+item.other_cents-item.refunds_cents,0);return{key,fixed:planFixed+staff+registeredFixed,variable,income,result:income-planFixed-staff-registeredFixed-variable,closure:closures.find(item=>item.period_start===`${key}-01`)}})},[expenses,revenues,planMonths,staffCosts,closures,categoryMap]);
  const totals = useMemo(() => {
    const total = monthExpenses.reduce((sum, expense) => sum + expense.total_cents, 0);
    const fixed = monthExpenses.filter((expense) => categoryMap.get(expense.category_id)?.cost_type === "fixed").reduce((sum, expense) => sum + expense.total_cents, 0);
    const paid = monthExpenses.filter((expense) => expense.payment_status === "paid").reduce((sum, expense) => sum + expense.total_cents, 0);
    const budget = categories.filter((category) => category.is_active).reduce((sum, category) => sum + category.monthly_budget_cents, 0);
    return { total, fixed, variable: total - fixed, paid, unpaid: total - paid, budget };
  }, [monthExpenses, categories, categoryMap]);
  const categoryTotals = useMemo(() => categories.map((category) => ({ category, total: monthExpenses.filter((expense) => expense.category_id === category.id).reduce((sum, expense) => sum + expense.total_cents, 0) })).filter((entry) => entry.total > 0).sort((a, b) => b.total - a.total), [categories, monthExpenses]);
  const trend = useMemo(() => makeTrend(range.start, range.end, periodMode, (start,end) => expenses.filter(e=>e.expense_date>=start&&e.expense_date<=end).reduce((s,e)=>s+e.total_cents,0)), [range,periodMode,expenses]);
  const revenueTrend = useMemo(() => makeTrend(range.start, range.end, periodMode, (start,end) => revenues.filter(r=>r.revenue_date>=start&&r.revenue_date<=end).reduce((s,r)=>s+r.cash_cents+r.pos_cents+r.other_cents-r.refunds_cents,0)), [range,periodMode,revenues]);
  const comparisonTrend=useMemo(()=>trend.map((entry,index)=>({...entry,outgoings:entry.total,income:revenueTrend[index]?.total??0})),[trend,revenueTrend]);
  const revenueTotal = monthRevenues.reduce((sum, entry) => sum + entry.cash_cents + entry.pos_cents + entry.other_cents - entry.refunds_cents, 0);
  const accruedPlanTotal = monthPlanRows.reduce((sum, entry) => { if (entry.competence_amount_cents == null) return sum; const monthStart=new Date(`${entry.competence_month}T12:00:00Z`); const monthEnd=new Date(Date.UTC(monthStart.getUTCFullYear(),monthStart.getUTCMonth()+1,0,12)); const overlapStart=new Date(`${range.start}T12:00:00Z`)>monthStart?new Date(`${range.start}T12:00:00Z`):monthStart; const overlapEnd=new Date(`${range.end}T12:00:00Z`)<monthEnd?new Date(`${range.end}T12:00:00Z`):monthEnd; const days=Math.max(0,Math.floor((overlapEnd.getTime()-overlapStart.getTime())/86400000)+1); return sum+Math.round(entry.competence_amount_cents*days/monthEnd.getUTCDate()); },0);
  const staffCostTotal=staffCosts.filter(cost=>cost.status==="confirmed"&&cost.competence_month>=range.start.slice(0,7)+"-01"&&cost.competence_month<=range.end).reduce((sum,cost)=>sum+Math.round(cost.confirmed_base_hours*cost.base_hourly_rate_cents+cost.confirmed_extra_hours*cost.extra_hourly_rate_cents),0);
  const accruedTotal = accruedPlanTotal + staffCostTotal + monthExpenses.reduce((sum, entry) => sum + entry.total_cents, 0);
  const operatingResult = revenueTotal - accruedTotal;
  const ledgerRows = useMemo(() => {
    const outflows = monthExpenses.map((expense) => ({ key: `expense-${expense.id}`, date: expense.expense_date, kind: "expense" as const, title: expense.description, detail: expense.supplier || categoryMap.get(expense.category_id)?.name || "Spesa", method: METHODS[expense.payment_method ?? ""] ?? "Non indicato", amount: -expense.total_cents, status: expense.payment_status === "paid" ? "Pagata" : expense.payment_status === "due" ? "Da pagare" : "Pianificata", source: expense }));
    const inflows = monthRevenues.flatMap((revenue) => {
      const entries = [
        revenue.cash_cents > 0 && { key: `revenue-${revenue.id}-cash`, title: "Incasso contanti", method: "Contanti", amount: revenue.cash_cents },
        revenue.pos_cents > 0 && { key: `revenue-${revenue.id}-pos`, title: "Incasso POS", method: "Carta / POS", amount: revenue.pos_cents },
        revenue.other_cents > 0 && { key: `revenue-${revenue.id}-other`, title: "Altri incassi", method: "Altro", amount: revenue.other_cents },
        revenue.refunds_cents > 0 && { key: `revenue-${revenue.id}-refund`, title: "Resi e storni", method: "Storno", amount: -revenue.refunds_cents },
      ].filter(Boolean) as { key: string; title: string; method: string; amount: number }[];
      return entries.map((entry) => ({ ...entry, date: revenue.revenue_date, kind: entry.amount >= 0 ? "revenue" as const : "expense" as const, detail: revenue.receipt_count == null ? "Chiusura giornaliera" : `${revenue.receipt_count} scontrini`, status: revenue.is_closed ? "Verificata" : "Da verificare", source: revenue }));
    });
    return [...outflows, ...inflows].sort((a, b) => b.date.localeCompare(a.date) || a.key.localeCompare(b.key));
  }, [monthExpenses, monthRevenues, categoryMap]);
  function run(action: (data: FormData) => Promise<ExpenseActionResult>, data: FormData, close: () => void) { setError(""); startTransition(async () => { const result = await action(data); if (!result.ok) { setError(result.error || "Operazione non riuscita."); return; } close(); router.refresh(); }); }
  const costStructureCard=<article className="expense-panel"><div className="expense-panel-title"><div><p className="admin-kicker">Struttura</p><h2>Fissi e variabili</h2></div></div><div className="cost-split"><div><span>Costi fissi</span><strong>{euro(totals.fixed)}</strong><i><b style={{width:`${totals.total?totals.fixed/totals.total*100:0}%`}}/></i></div><div><span>Costi variabili</span><strong>{euro(totals.variable)}</strong><i><b style={{width:`${totals.total?totals.variable/totals.total*100:0}%`}}/></i></div></div></article>;
  const revenueCompositionCard=<article className="expense-panel"><div className="expense-panel-title"><div><p className="admin-kicker">Composizione entrate</p><h2>Per modalità</h2></div></div><RevenueComposition revenues={monthRevenues}/></article>;
  const dueDatesCard=<article className="expense-panel"><div className="expense-panel-title"><div><p className="admin-kicker">Attenzione</p><h2>Prossime scadenze</h2></div></div><div className="due-list">{monthExpenses.filter(expense=>expense.payment_status!=="paid").sort((a,b)=>(a.due_date??"9999").localeCompare(b.due_date??"9999")).slice(0,5).map(expense=><button onClick={()=>setExpenseEditor(expense)} key={expense.id}><i style={{background:categoryMap.get(expense.category_id)?.color}}/><span><strong>{expense.description}</strong><small>{expense.due_date?new Date(`${expense.due_date}T12:00:00Z`).toLocaleDateString("it-IT"):"Senza scadenza"}</small></span><b>{euro(expense.total_cents)}</b></button>)}{!monthExpenses.some(expense=>expense.payment_status!=="paid")&&<p className="expense-empty">Nessuna scadenza aperta.</p>}</div></article>;

  return <main className={`admin-container expenses-page ${styles.expensesPage}`}>
    <div className="expenses-topbar"><Link className="admin-inline-link" href="/admin"><ArrowLeft size={15} /> Dashboard</Link><div className="expense-tabs"><button className={tab === "overview" ? "active" : ""} onClick={() => setTab("overview")}><ChartNoAxesCombined size={15} /> Panoramica</button><button className={tab === "daily" ? "active" : ""} onClick={() => setTab("daily")}><ReceiptText size={15} /> Spese rapide</button><button className={tab === "revenues" ? "active" : ""} onClick={() => setTab("revenues")}><Banknote size={15} /> Incassi</button><button className={tab === "plans" ? "active" : ""} onClick={() => setTab("plans")}><CalendarClock size={15} /> Costi fissi</button><button className={tab === "ledger" ? "active" : ""} onClick={() => { setPeriodMode("month"); setTab("ledger"); }}><Landmark size={15} /> Movimenti</button><button className={tab === "closures" ? "active" : ""} onClick={() => setTab("closures")}><CalendarCheck2 size={15} /> Chiusure</button><button className={tab === "categories" ? "active" : ""} onClick={() => setTab("categories")}><Tags size={15} /> Categorie</button></div></div>
    <header className="expenses-heading"><div><p className="admin-kicker">Controllo di gestione</p><h1>Gestione economica</h1><p>Una visione chiara di budget, pagamenti e andamento del locale.</p></div>{tab==="ledger"?<div className="expenses-heading-actions period-controls fixed-cost-period"><label><span>Mese</span><input type="month" value={month} onChange={e=>setMonth(e.target.value)}/></label></div>:tab!=="plans"&&tab!=="closures"&&<div className="expenses-heading-actions period-controls"><label><span>Vista</span><select value={periodMode} onChange={(event)=>setPeriodMode(event.target.value as typeof periodMode)}><option value="day">Giornaliera</option><option value="week">Settimanale</option><option value="month">Mensile</option><option value="quarter">Trimestrale</option><option value="year">Annuale</option></select></label><label><span>Periodo</span>{periodMode==="day"?<input type="date" value={day} onChange={e=>setDay(e.target.value)}/>:periodMode==="week"?<input type="week" value={week} onChange={e=>setWeek(e.target.value)}/>:periodMode==="month"?<input type="month" value={month} onChange={e=>setMonth(e.target.value)}/>:periodMode==="quarter"?<select value={quarter} onChange={e=>setQuarter(e.target.value)}>{Array.from({length:11},(_,index)=>new Date().getFullYear()-5+index).flatMap(value=>[1,2,3,4].map(item=><option value={`${value}-Q${item}`} key={`${value}-Q${item}`}>{item}° trimestre {value}</option>))}</select>:<input type="number" min="2020" max="2100" value={year} onChange={e=>setYear(e.target.value)}/>}</label><button className="admin-action admin-action-primary admin-action-create expense-new-button" onClick={()=>setExpenseEditor("new")}><Plus size={16}/> Nuova spesa</button></div>}</header>
    {error && <div className="staff-alert"><span>{error}</span><button onClick={() => setError("")}><X size={16} /></button></div>}
    {tab === "ledger" && <section className={`expense-panel expense-movements ledger-panel ${styles.ledgerPanel}`}><div className="ledger-hero"><div className="ledger-hero-copy"><p className="admin-kicker">Prima nota · {monthLabel(month)}</p><h2>Prospetto completo</h2><p>Entrate, costi di competenza e movimenti del periodo in un unico riepilogo.</p></div><div className="ledger-metric-grid"><article className="ledger-metric metric-income"><span>Entrate</span><strong>{euro(revenueTotal)}</strong><small>Incassi</small></article><article className="ledger-metric metric-fixed"><span>Costi fissi</span><strong>{euro(fixedCompetenceTotal)}</strong><small>Competenza</small></article><article className="ledger-metric metric-variable"><span>Altri costi</span><strong>{euro(totals.total)}</strong><small>Registrati</small></article><article className={`ledger-metric metric-result ${revenueTotal-fixedCompetenceTotal-totals.total>=0?"positive":"negative"}`}><span>Risultato</span><strong>{euro(revenueTotal-fixedCompetenceTotal-totals.total)}</strong><small>Saldo</small></article></div></div><div className={`fixed-cost-accordion ${fixedLedgerOpen?"is-open":""}`}><button className="fixed-cost-accordion-trigger" onClick={()=>setFixedLedgerOpen(value=>!value)} aria-expanded={fixedLedgerOpen}><span className="fixed-cost-accordion-icon"><CalendarClock/></span><span className="fixed-cost-accordion-copy"><small>Costi ricorrenti</small><strong>Competenze dei costi fissi</strong><em>{fixedCompetenceRows.length} {fixedCompetenceRows.length===1?"voce":"voci"} nel mese</em></span><span className="fixed-cost-accordion-total"><small>Totale competenza</small><strong>{euro(fixedCompetenceTotal)}</strong></span><ChevronDown className="fixed-cost-accordion-chevron"/></button>{fixedLedgerOpen&&<div className="fixed-cost-accordion-body">{fixedCompetenceRows.map(item=><article className="fixed-cost-detail-row" key={item.key}><span className="fixed-cost-detail-marker"/><span className="fixed-cost-detail-copy"><strong>{item.title}</strong><small className={`status-${item.status}`}>{item.status==="paid"?"Pagata":item.status==="confirmed"?"Confermata":"Pianificata"}</small></span><strong className="fixed-cost-detail-amount">{euro(item.amount)}</strong></article>)}{!fixedCompetenceRows.length&&<p>Nessuna competenza fissa nel mese.</p>}</div>}</div><div className="expense-table-wrap"><table className="ledger-table"><thead><tr><th>Data</th><th>Tipo</th><th>Descrizione</th><th>Riferimento</th><th>Metodo</th><th>Stato</th><th>Importo</th><th /></tr></thead><tbody>{ledgerRows.map(row=>{const expense=row.kind==="expense"&&!row.key.includes("refund")?row.source as Expense:null;const costType=expense?categoryMap.get(expense.category_id)?.cost_type:null;return <tr key={row.key}><td>{new Date(`${row.date}T12:00:00Z`).toLocaleDateString("it-IT")}</td><td><span className={`ledger-kind ${row.amount>=0?"in":"out"}`}>{row.amount>=0?"Entrata":costType==="fixed"?"Costo fisso":"Costo variabile"}</span></td><td><strong>{row.title}</strong></td><td>{row.detail}</td><td>{row.method}</td><td>{row.status}</td><td><strong className={row.amount>=0?"ledger-positive":"ledger-negative"}>{row.amount>=0?"+":"−"}{euro(Math.abs(row.amount))}</strong></td><td><button className="employee-edit" onClick={()=>row.kind==="revenue"?setRevenueEditor(row.source as Revenue):(row.key.includes("refund")?setRevenueEditor(row.source as Revenue):setExpenseEditor(row.source as Expense))}><Pencil size={14}/></button></td></tr>})}</tbody></table>{!ledgerRows.length&&!fixedCompetenceRows.length&&<p className="expense-empty">Nessun movimento nel periodo selezionato.</p>}</div></section>}
    {!financeReady && <div className="staff-alert"><span>Esegui <strong>supabase/finance-management-migration.sql</strong> nel SQL Editor di Supabase per attivare costi fissi e incassi.</span></div>}
    {tab==="closures"&&<section className="monthly-closures"><div className="closures-intro"><div><p className="admin-kicker">Controllo periodi</p><h2>Chiusure mensili</h2><p>Verifica entrate e costi del mese prima di consolidare lo storico.</p></div><span>{closures.length} mesi chiusi</span></div>{!historyReady&&<div className="staff-alert">Esegui fixed-cost-history-migration.sql su Supabase.</div>}<div className="closure-history">{closureSummaries.map(summary=><article className={summary.closure?"closed":""} key={summary.key}><header><div><span className={`month-lock-state ${summary.closure?"closed":"open"}`}>{summary.closure?"Chiuso":"Aperto"}</span><h3>{monthLabel(summary.key)}</h3>{summary.closure&&<small>Chiuso il {new Date(summary.closure.closed_at).toLocaleDateString("it-IT")}</small>}</div><button className={`admin-action ${summary.closure?"admin-action-secondary":"admin-action-primary"}`} onClick={()=>{if(!confirm(summary.closure?"Riaprire questo mese? I dati torneranno modificabili.":"Confermare le competenze e chiudere questo mese?"))return;const data=new FormData();data.set("month",summary.key);run(summary.closure?reopenFinancialMonth:closeFinancialMonth,data,()=>{})}}>{summary.closure?"Riapri mese":"Conferma e chiudi"}</button></header><div className="closure-values"><div><span>Entrate</span><strong className="ledger-positive">{euro(summary.income)}</strong></div><div><span>Costi fissi</span><strong>{euro(summary.fixed)}</strong></div><div><span>Costi variabili</span><strong>{euro(summary.variable)}</strong></div><div><span>Risultato</span><strong className={summary.result>=0?"ledger-positive":"ledger-negative"}>{euro(summary.result)}</strong></div></div></article>)}</div></section>}

    {tab === "overview" && <>
      <section className="expense-kpis"><Kpi icon={<Banknote />} label="Incassi del periodo" value={euro(revenueTotal)} detail={`${monthRevenues.length} giornate registrate`} tone="green" /><Kpi icon={<CircleEuro />} label="Costi di competenza" value={euro(accruedTotal)} detail="Fissi + movimenti del periodo" tone="orange" /><Kpi icon={<ChartNoAxesCombined />} label="Risultato operativo" value={euro(operatingResult)} detail="Prima di imposte e rettifiche" tone={operatingResult >= 0 ? "green" : "red"} /><Kpi icon={<CalendarClock />} label="Da pagare" value={euro(totals.unpaid)} detail={`${monthExpenses.filter((expense) => expense.payment_status !== "paid").length} voci aperte`} tone="purple" /></section>
      {periodMode==="year"?<><section className="expense-chart-grid"><article className="expense-panel expense-trend"><div className="expense-panel-title"><div><p className="admin-kicker">Andamento costi</p><h2>{range.label}</h2></div><span>{euro(trend.reduce((sum,entry)=>sum+entry.total,0))}</span></div><TrendChart data={trend}/></article><article className="expense-panel"><div className="expense-panel-title"><div><p className="admin-kicker">Composizione costi</p><h2>Per categoria</h2></div></div><CategoryDonut data={categoryTotals} total={totals.total}/></article></section><section className="expense-chart-grid revenue-overview">{costStructureCard}<article className="expense-panel expense-trend"><div className="expense-panel-title"><div><p className="admin-kicker">Andamento entrate</p><h2>{range.label}</h2></div><span>{euro(revenueTrend.reduce((sum,entry)=>sum+entry.total,0))}</span></div><TrendChart data={revenueTrend} tone="green"/></article></section></>:<><section className="expense-panel cashflow-comparison"><div className="expense-panel-title cashflow-comparison-heading"><div><p className="admin-kicker">Entrate vs uscite</p><h2>{range.label}</h2></div><div className="cashflow-totals"><span><i className="income"/>Entrate <strong>{euro(revenueTotal)}</strong></span><span><i className="outgoing"/>Uscite <strong>{euro(totals.total)}</strong></span></div></div><ComparisonTrendChart data={comparisonTrend}/></section><section className="expense-chart-grid revenue-overview"><article className="expense-panel"><div className="expense-panel-title"><div><p className="admin-kicker">Composizione costi</p><h2>Per categoria</h2></div></div><CategoryDonut data={categoryTotals} total={totals.total}/></article>{costStructureCard}</section></>}
      <section className="expense-chart-grid expense-secondary-grid">{revenueCompositionCard}{dueDatesCard}</section>
    </>}

    {tab === "plans" && <><section className="fixed-cost-toolbar fixed-cost-toolbar-simple"><div><span className={`month-lock-state ${monthClosed?"closed":"open"}`}>{monthClosed?"Mese chiuso":"Mese aperto"}</span><p>{monthClosed?"Competenze conservate nello storico. Per modificarle riapri il mese dalla sezione Chiusure.":"Riepilogo delle competenze fisse previste e confermate."}</p></div><div><button className="admin-action admin-action-secondary" onClick={()=>setShowPlanHistory(value=>!value)}>{showPlanHistory?"Mostra riepilogo":"Versioni e disattivati"}</button><button className="admin-action admin-action-primary admin-action-create" onClick={()=>setPlanEditor("new")}><Plus size={16}/> Nuovo costo</button></div></section>{!historyReady&&<div className="staff-alert">Esegui fixed-cost-history-migration.sql su Supabase per attivare storico e chiusure.</div>}<section className="expense-panel expense-movements"><div className="expense-panel-title fixed-cost-panel-title"><div><p className="admin-kicker">{showPlanHistory?"Archivio completo":"Competenza mensile"}</p><h2>Costi fissi e ricorrenti</h2></div><label className="fixed-cost-month-picker"><span>Mese di competenza</span><input type="month" value={month} onChange={e=>setMonth(e.target.value)}/></label></div><div className="fixed-plan-grid">{fixedCostPlans.map((plan)=>{const row=planMonths.find(item=>item.plan_id===plan.id&&item.competence_month===`${month}-01`);return <article className={!plan.is_active?"inactive":""} key={plan.id}><div><span>{!plan.is_active?`Versione ${plan.version_number} · archiviata`:plan.is_estimate?"Stima":"Confermato"}</span><h3>{plan.name}</h3><p>{plan.annual_amount_cents===null?"Importo da stimare":`${euro(Math.round(plan.annual_amount_cents/frequencyMultiplier(plan.payment_frequency)))} · ${frequencyLabel(plan.payment_frequency)}`}</p><small>Valida dal {new Date(`${plan.competence_start}T12:00:00Z`).toLocaleDateString("it-IT")} al {new Date(`${plan.competence_end}T12:00:00Z`).toLocaleDateString("it-IT")}</small></div><div className="plan-month-value"><small>Competenza del mese</small><strong>{row?.competence_amount_cents==null?"—":euro(row.competence_amount_cents)}</strong><span className={`expense-status status-${row?.status??"planned"}`}>{row?.status==="paid"?"Pagata":row?.status==="confirmed"?"Confermata":"Pianificata"}</span>{row&&!monthClosed&&<button onClick={()=>{const value=prompt("Importo consuntivo (€)",((row.competence_amount_cents??0)/100).toFixed(2));if(value===null)return;const data=new FormData();data.set("id",String(row.id));data.set("amount",value);data.set("status","confirmed");run(validateCostMonth,data,()=>{})}}>Conferma</button>}</div>{plan.is_active&&!monthClosed&&<button className="employee-edit" onClick={()=>setPlanEditor(plan)}><Pencil size={14}/></button>}</article>})}{!fixedCostPlans.length&&<p className="expense-empty">Nessun costo configurato per questo periodo.</p>}</div></section></>}

    {tab === "daily" && <section className="daily-entry-layout"><article className="expense-panel quick-entry-card"><p className="admin-kicker">Inserimento veloce</p><h2>Spesa giornaliera</h2><p>Per consegne, acquisti e piccoli costi sostenuti durante la giornata.</p><button className="admin-action admin-action-primary admin-action-create" onClick={() => setExpenseEditor("new")}><Plus size={16}/> Registra una spesa</button></article><article className="expense-panel"><div className="expense-panel-title"><h2>Ultime spese</h2></div><div className="compact-ledger">{monthExpenses.slice(0,8).map((expense) => <button key={expense.id} onClick={() => setExpenseEditor(expense)}><span><strong>{expense.description}</strong><small>{new Date(`${expense.expense_date}T12:00:00Z`).toLocaleDateString("it-IT")}</small></span><b>{euro(expense.total_cents)}</b></button>)}</div></article></section>}

    {tab === "revenues" && <section className="expense-panel expense-movements"><div className="expense-panel-title"><div><p className="admin-kicker">Chiusure giornaliere</p><h2>Incassi cash e POS</h2></div><button className="admin-action admin-action-primary admin-action-create" onClick={() => setRevenueEditor("new")}><Plus size={16}/> Inserisci incasso</button></div><div className="revenue-summary"><div><span>Contanti</span><strong>{euro(monthRevenues.reduce((s,r) => s+r.cash_cents,0))}</strong></div><div><span>POS</span><strong>{euro(monthRevenues.reduce((s,r) => s+r.pos_cents,0))}</strong></div><div><span>Totale netto</span><strong>{euro(revenueTotal)}</strong></div></div><div className="compact-ledger">{monthRevenues.map((entry) => <button key={entry.id} onClick={() => setRevenueEditor(entry)}><span><strong>{new Date(`${entry.revenue_date}T12:00:00Z`).toLocaleDateString("it-IT")}</strong><small>Cash {euro(entry.cash_cents)} · POS {euro(entry.pos_cents)} · {entry.receipt_count ?? 0} scontrini</small></span><b>{euro(entry.cash_cents+entry.pos_cents+entry.other_cents-entry.refunds_cents)}</b></button>)}</div></section>}

    {tab === "expenses" && <section className="expense-panel expense-movements"><div className="expense-panel-title"><div><p className="admin-kicker">{monthLabel(month)}</p><h2>Movimenti del mese</h2></div><span>{monthExpenses.length} voci</span></div><div className="expense-table-wrap"><table><thead><tr><th>Data</th><th>Descrizione</th><th>Categoria</th><th>Fornitore</th><th>Stato</th><th>Totale</th><th /></tr></thead><tbody>{monthExpenses.map((expense) => { const category = categoryMap.get(expense.category_id); const isOverdue = expense.payment_status !== "paid" && expense.due_date && expense.due_date < new Date().toISOString().slice(0, 10); return <tr key={expense.id}><td>{new Date(`${expense.expense_date}T12:00:00Z`).toLocaleDateString("it-IT")}</td><td><strong>{expense.description}</strong>{expense.is_estimate && <small>Stima</small>}</td><td><span className="expense-category"><i style={{ background: category?.color }} />{category?.name}</span></td><td>{expense.supplier || "—"}</td><td><span className={`expense-status status-${isOverdue ? "overdue" : expense.payment_status}`}>{isOverdue ? "Scaduta" : STATUS[expense.payment_status]}</span></td><td><strong>{euro(expense.total_cents)}</strong></td><td><button className="employee-edit" onClick={() => setExpenseEditor(expense)}><Pencil size={14} /></button></td></tr>; })}</tbody></table>{!monthExpenses.length && <p className="expense-empty">Nessuna spesa nel periodo selezionato.</p>}</div></section>}

    {tab === "categories" && <section className="expense-categories"><div className="categories-intro"><div><p className="admin-kicker">Configurazione</p><h2>Categorie e budget</h2><p>Il budget complessivo deriva dalla somma dei limiti mensili delle categorie attive.</p></div><button className="admin-action admin-action-primary admin-action-create" onClick={() => setCategoryEditor("new")}><Plus size={16} /> Nuova categoria</button></div><div className="expense-category-grid">{categories.map((category) => <article className={category.is_active ? "" : "inactive"} key={category.id}><i style={{ background: category.color }} /><div><span>{category.cost_type === "fixed" ? "Costo fisso" : "Costo variabile"}</span><h3>{category.name}</h3><p>Budget mensile <strong>{euro(category.monthly_budget_cents)}</strong></p></div><button className="employee-edit" onClick={() => setCategoryEditor(category)}><Settings2 size={15} /></button></article>)}</div></section>}

    {expenseEditor && <ExpenseModal expense={expenseEditor === "new" ? null : expenseEditor} categories={categories} pending={pending} onClose={() => setExpenseEditor(null)} onSave={(data) => run(expenseEditor === "new" ? createExpense : updateExpense, data, () => setExpenseEditor(null))} onDelete={(data) => run(deleteExpense, data, () => setExpenseEditor(null))} />}
    {categoryEditor && <CategoryModal category={categoryEditor === "new" ? null : categoryEditor} pending={pending} onClose={() => setCategoryEditor(null)} onSave={(data) => run(categoryEditor === "new" ? createExpenseCategory : updateExpenseCategory, data, () => setCategoryEditor(null))} />}
    {planEditor && <PlanModal plan={planEditor === "new" ? null : planEditor} categories={categories} selectedMonth={month} pending={pending} onClose={() => setPlanEditor(null)} onSave={(data) => run(planEditor === "new" ? createRecurringPlan : updateRecurringPlan, data, () => setPlanEditor(null))} />}
    {revenueEditor && <RevenueModal revenue={revenueEditor === "new" ? null : revenueEditor} pending={pending} onClose={() => setRevenueEditor(null)} onSave={(data) => run(saveDailyRevenue, data, () => setRevenueEditor(null))} />}
  </main>;
}

function Kpi({ icon, label, value, detail, tone }: { icon: React.ReactNode; label: string; value: string; detail: string; tone: string }) { return <article className={`expense-kpi tone-${tone}`}><span>{icon}</span><div><small>{label}</small><strong>{value}</strong><p>{detail}</p></div></article>; }
function TrendChart({ data, tone = "orange" }: { data: { key: string; label: string; total: number }[]; tone?: "orange"|"green" }) { const max = Math.max(1, ...data.map((entry) => entry.total)); return <div className={`trend-chart trend-${tone}`} style={{gridTemplateColumns:`repeat(${Math.max(1,data.length)},minmax(0,1fr))`}}>{data.map((entry) => <div key={entry.key}><span>{entry.total ? euro(entry.total) : "—"}</span><i><b style={{ height: `${Math.max(3, entry.total / max * 100)}%` }} /></i><small>{entry.label}</small></div>)}</div>; }
function ComparisonTrendChart({data}:{data:{key:string;label:string;income:number;outgoings:number}[]}){const max=Math.max(1,...data.flatMap(entry=>[entry.income,entry.outgoings]));return <div className={`comparison-trend ${data.length===1?"single":""}`} style={{gridTemplateColumns:`repeat(${Math.max(1,data.length)},minmax(0,1fr))`}}>{data.map(entry=>{const incomeHeight=entry.income?Math.max(5,entry.income/max*100):0;const outgoingHeight=entry.outgoings?Math.max(5,entry.outgoings/max*100):0;return <div className="comparison-period" key={entry.key}><div className="comparison-bars"><i><span className="comparison-value income" style={{bottom:`calc(${incomeHeight}% + .3rem)`}}>{euro(entry.income)}</span><b className="income" style={{height:`${incomeHeight}%`}}/></i><i><span className="comparison-value outgoing" style={{bottom:`calc(${outgoingHeight}% + .3rem)`}}>{euro(entry.outgoings)}</span><b className="outgoing" style={{height:`${outgoingHeight}%`}}/></i></div><small>{entry.label}</small></div>})}</div>}
function RevenueComposition({revenues}:{revenues:Revenue[]}){const data=[{label:"Contanti",value:revenues.reduce((s,r)=>s+r.cash_cents,0),color:"#E8650A"},{label:"POS",value:revenues.reduce((s,r)=>s+r.pos_cents,0),color:"#248A73"},{label:"Altri",value:revenues.reduce((s,r)=>s+r.other_cents,0),color:"#7C5CFC"}],total=data.reduce((s,d)=>s+d.value,0);let offset=0;return <div className="donut-layout revenue-donut-layout"><div className="expense-donut"><svg viewBox="0 0 120 120"><circle className="donut-track" cx="60" cy="60" r="45" fill="none" strokeWidth="14"/><>{data.map(item=>{const length=total?item.value/total*100:0;const current=offset;offset+=length;return <circle key={item.label} cx="60" cy="60" r="45" pathLength="100" fill="none" stroke={item.color} strokeWidth="14" strokeDasharray={`${length} ${100-length}`} strokeDashoffset={-current}/>})}</></svg><div><strong>{euro(total)}</strong><span>Entrate</span></div></div><div className="donut-legend">{data.map(item=><div key={item.label}><i style={{background:item.color}}/><span>{item.label}<small>{euro(item.value)}</small></span><strong>{total?Math.round(item.value/total*100):0}%</strong></div>)}</div></div>}
function CategoryDonut({ data, total }: { data: { category: Category; total: number }[]; total: number }) { const segments = data.map((entry, index) => ({ ...entry, length: total ? entry.total / total * 100 : 0, offset: total ? data.slice(0, index).reduce((sum, previous) => sum + previous.total / total * 100, 0) : 0 })); return <div className="donut-layout"><div className="expense-donut"><svg viewBox="0 0 120 120">{segments.map(({ category, length, offset }) => <circle key={category.id} cx="60" cy="60" r="45" pathLength="100" fill="none" stroke={category.color} strokeWidth="14" strokeDasharray={`${length} ${100 - length}`} strokeDashoffset={-offset} />)}</svg><div><strong>{euro(total)}</strong><span>Totale</span></div></div><div className="donut-legend">{data.slice(0, 6).map(({ category, total: value }) => <div key={category.id}><i style={{ background: category.color }} /><span>{category.name}</span><strong>{total ? Math.round(value / total * 100) : 0}%</strong></div>)}</div></div>; }

function ExpenseModal({ expense, categories, pending, onClose, onSave, onDelete }: { expense: Expense | null; categories: Category[]; pending: boolean; onClose: () => void; onSave: (data: FormData) => void; onDelete: (data: FormData) => void }) {
  const [status, setStatus] = useState(expense?.payment_status ?? "due"); const defaultDate = expense?.expense_date ?? currentDay();
  return <div className="admin-modal-backdrop" onMouseDown={(event) => { if (event.target === event.currentTarget) onClose(); }}><section className="admin-modal admin-modal-wide"><button className="modal-close" onClick={onClose}><X /></button><p className="admin-kicker">Contabilità interna</p><h2>{expense ? "Modifica spesa" : "Nuova spesa"}</h2><form className="admin-edit-grid" onSubmit={(event) => { event.preventDefault(); onSave(new FormData(event.currentTarget)); }}><input type="hidden" name="id" value={expense?.id ?? ""} /><label className="admin-field admin-field-wide"><span>Descrizione</span><input name="description" defaultValue={expense?.description ?? ""} required /></label><label className="admin-field"><span>Categoria</span><select name="category_id" defaultValue={expense?.category_id}>{categories.filter((category) => category.is_active || category.id === expense?.category_id).map((category) => <option value={category.id} key={category.id}>{category.name}</option>)}</select></label><label className="admin-field"><span>Fornitore</span><input name="supplier" defaultValue={expense?.supplier ?? ""} /></label><label className="admin-field"><span>Data competenza</span><input name="expense_date" type="date" defaultValue={defaultDate} required /></label><label className="admin-field"><span>Scadenza</span><input name="due_date" type="date" defaultValue={expense?.due_date ?? ""} /></label><label className="admin-field"><span>Imponibile (€)</span><input name="amount_net" type="number" min="0" step="0.01" defaultValue={expense ? (expense.amount_net_cents / 100).toFixed(2) : ""} required /></label><label className="admin-field"><span>IVA (€)</span><input name="vat" type="number" min="0" step="0.01" defaultValue={expense ? (expense.vat_cents / 100).toFixed(2) : "0.00"} required /></label><label className="admin-field"><span>Stato</span><select name="payment_status" value={status} onChange={(event) => setStatus(event.target.value as Expense["payment_status"])}><option value="planned">Pianificata</option><option value="due">Da pagare</option><option value="paid">Pagata</option></select></label><label className="admin-field"><span>{status === "paid" ? "Data pagamento" : "Numero fattura"}</span>{status === "paid" ? <input name="paid_date" type="date" defaultValue={expense?.paid_date ?? defaultDate} /> : <input name="invoice_number" defaultValue={expense?.invoice_number ?? ""} />}</label>{status === "paid" && <input type="hidden" name="invoice_number" value={expense?.invoice_number ?? ""} />}<label className="admin-field"><span>Metodo pagamento</span><select name="payment_method" defaultValue={expense?.payment_method ?? ""}><option value="">Non indicato</option>{Object.entries(METHODS).map(([value, label]) => <option value={value} key={value}>{label}</option>)}</select></label><label className="admin-field"><span>Ricorrenza</span><select name="recurrence" defaultValue={expense?.recurrence ?? "none"}>{Object.entries(RECURRENCES).map(([value, label]) => <option value={value} key={value}>{label}</option>)}</select></label><label className="admin-field admin-field-wide"><span>Note</span><textarea name="notes" rows={3} defaultValue={expense?.notes ?? ""} /></label><label className="admin-check"><input name="is_estimate" type="checkbox" defaultChecked={expense?.is_estimate} /> Valore stimato / previsionale</label><div className="modal-actions admin-field-wide">{expense && <button type="button" className="admin-action admin-action-danger" disabled={pending} onClick={() => { if (!confirm("Eliminare definitivamente questa spesa?")) return; const data = new FormData(); data.set("id", String(expense.id)); onDelete(data); }}>Elimina</button>}<button type="button" className="admin-action admin-action-secondary" onClick={onClose}>Annulla</button><button className="admin-action admin-action-primary" disabled={pending}>{pending ? "Salvataggio…" : "Salva spesa"}</button></div></form></section></div>;
}
function CategoryModal({ category, pending, onClose, onSave }: { category: Category | null; pending: boolean; onClose: () => void; onSave: (data: FormData) => void }) { return <div className="admin-modal-backdrop" onMouseDown={(event) => { if (event.target === event.currentTarget) onClose(); }}><section className="admin-modal"><button className="modal-close" onClick={onClose}><X /></button><p className="admin-kicker">Budget</p><h2>{category ? "Modifica categoria" : "Nuova categoria"}</h2><form className="admin-edit-grid" onSubmit={(event) => { event.preventDefault(); onSave(new FormData(event.currentTarget)); }}><input type="hidden" name="id" value={category?.id ?? ""} /><label className="admin-field admin-field-wide"><span>Nome</span><input name="name" defaultValue={category?.name ?? ""} required /></label><label className="admin-field"><span>Tipologia costo</span><select name="cost_type" defaultValue={category?.cost_type ?? "variable"}><option value="fixed">Fisso</option><option value="variable">Variabile</option></select></label><label className="admin-field"><span>Colore</span><input name="color" type="color" defaultValue={category?.color ?? "#E8650A"} /></label><label className="admin-field admin-field-wide"><span>Budget mensile (€)</span><input name="monthly_budget" type="number" min="0" step="0.01" defaultValue={category ? (category.monthly_budget_cents / 100).toFixed(2) : "0.00"} required /></label>{category && <label className="admin-check"><input name="is_active" type="checkbox" defaultChecked={category.is_active} /> Categoria attiva</label>}<div className="modal-actions admin-field-wide"><button type="button" className="admin-action admin-action-secondary" onClick={onClose}>Annulla</button><button className="admin-action admin-action-primary" disabled={pending}>{pending ? "Salvataggio…" : "Salva categoria"}</button></div></form></section></div>; }

function RevenueModal({ revenue, pending, onClose, onSave }: { revenue: Revenue | null; pending: boolean; onClose: () => void; onSave: (data: FormData) => void }) { return <div className="admin-modal-backdrop"><section className="admin-modal"><button className="modal-close" onClick={onClose}><X/></button><p className="admin-kicker">Prima nota</p><h2>Incasso giornaliero</h2><form className="admin-edit-grid" onSubmit={(e) => { e.preventDefault(); onSave(new FormData(e.currentTarget)); }}><label className="admin-field admin-field-wide"><span>Giorno</span><input name="revenue_date" type="date" defaultValue={revenue?.revenue_date ?? currentDay()} required/></label><label className="admin-field"><span>Contanti (€)</span><input name="cash" type="number" min="0" step=".01" defaultValue={((revenue?.cash_cents ?? 0)/100).toFixed(2)} required/></label><label className="admin-field"><span>POS (€)</span><input name="pos" type="number" min="0" step=".01" defaultValue={((revenue?.pos_cents ?? 0)/100).toFixed(2)} required/></label><label className="admin-field"><span>Altri incassi (€)</span><input name="other" type="number" min="0" step=".01" defaultValue={((revenue?.other_cents ?? 0)/100).toFixed(2)}/></label><label className="admin-field"><span>Resi/storni (€)</span><input name="refunds" type="number" min="0" step=".01" defaultValue={((revenue?.refunds_cents ?? 0)/100).toFixed(2)}/></label><label className="admin-field"><span>Numero scontrini</span><input name="receipt_count" type="number" min="0" defaultValue={revenue?.receipt_count ?? ""}/></label><label className="admin-field admin-field-wide"><span>Note</span><textarea name="notes" defaultValue={revenue?.notes ?? ""}/></label><label className="admin-check"><input name="is_closed" type="checkbox" defaultChecked={revenue?.is_closed}/> Giornata verificata e chiusa</label><div className="modal-actions admin-field-wide"><button type="button" className="admin-action admin-action-secondary" onClick={onClose}>Annulla</button><button className="admin-action admin-action-primary" disabled={pending}>Salva incasso</button></div></form></section></div>; }

function PlanModal({ plan, categories, selectedMonth, pending, onClose, onSave }: { plan: Plan | null; categories: Category[]; selectedMonth: string; pending: boolean; onClose: () => void; onSave: (data: FormData) => void }) { const monthNames=["Gen","Feb","Mar","Apr","Mag","Giu","Lug","Ago","Set","Ott","Nov","Dic"]; return <div className="admin-modal-backdrop"><section className="admin-modal admin-modal-wide"><button className="modal-close" onClick={onClose}><X/></button><p className="admin-kicker">Pianificazione</p><h2>{plan ? "Modifica costo fisso" : "Nuovo costo fisso"}</h2><form className="admin-edit-grid" onSubmit={(e) => { e.preventDefault(); onSave(new FormData(e.currentTarget)); }}><input type="hidden" name="id" value={plan?.id ?? ""}/><label className="admin-field admin-field-wide"><span>Nome</span><input name="name" defaultValue={plan?.name ?? ""} required/></label><label className="admin-field"><span>Categoria</span><select name="category_id" defaultValue={plan?.category_id ?? ""}><option value="">Nessuna</option>{categories.map(c=><option key={c.id} value={c.id}>{c.name}</option>)}</select></label><label className="admin-field"><span>Fornitore</span><input name="supplier" defaultValue={plan?.supplier ?? ""}/></label><label className="admin-field"><span>Importo (€)</span><input name="annual_amount" type="number" min="0" step=".01" defaultValue={plan?.annual_amount_cents == null ? "" : (plan.annual_amount_cents/frequencyMultiplier(plan.payment_frequency)/100).toFixed(2)} placeholder="Da stimare"/></label><label className="admin-field"><span>Periodicità</span><select name="payment_frequency" defaultValue={plan?.payment_frequency ?? "monthly"}><option value="monthly">Mensile</option><option value="bimonthly">Bimestrale</option><option value="quarterly">Trimestrale</option><option value="yearly">Annuale</option><option value="custom">Personalizzata</option></select></label><label className="admin-field"><span>{plan ? "Modifica valida da" : "Valido da"}</span><input name="competence_start" type="date" defaultValue={plan?.competence_start ?? `${selectedMonth}-01`} required/></label><label className="admin-field"><span>Valido fino al</span><input name="competence_end" type="date" defaultValue={plan?.competence_end ?? (()=>{const date=new Date(`${selectedMonth}-01T12:00:00Z`);date.setUTCFullYear(date.getUTCFullYear()+1);date.setUTCDate(date.getUTCDate()-1);return date.toISOString().slice(0,10)})()} required/></label><label className="admin-field"><span>Giorno pagamento</span><input name="payment_day" type="number" min="1" max="28" defaultValue={plan?.payment_day ?? 1}/></label><div className="admin-field admin-field-wide"><span>Mesi di pagamento / notifica</span><div className="month-checks">{monthNames.map((label,i)=><label key={label}><input type="checkbox" name="payment_months" value={i+1} defaultChecked={plan?.payment_months.includes(i+1)}/>{label}</label>)}</div></div><label className="admin-field"><span>Metodo</span><select name="payment_method" defaultValue={plan?.payment_method ?? ""}><option value="">Non indicato</option>{Object.entries(METHODS).map(([v,l])=><option key={v} value={v}>{l}</option>)}</select></label><label className="admin-field admin-field-wide"><span>Note</span><textarea name="notes" defaultValue={plan?.notes ?? ""}/></label><label className="admin-check"><input name="is_estimate" type="checkbox" defaultChecked={plan?.is_estimate ?? true}/> Valore stimato</label>{plan&&<label className="admin-check"><input name="is_active" type="checkbox" defaultChecked={plan.is_active}/> Piano attivo</label>}<div className="modal-actions admin-field-wide"><button type="button" className="admin-action admin-action-secondary" onClick={onClose}>Annulla</button><button className="admin-action admin-action-primary" disabled={pending}>Salva costo</button></div></form></section></div>; }
